43	    #[test]
44	    fn is_bare_semver_accepts_three_part_numeric() {
45	        assert!(is_bare_semver("1.2.3"));
46	        assert!(is_bare_semver("0.0.0"));
47	    }
48	
49	    #[test]
50	    fn is_bare_semver_rejects_non_digit_start() {
51	        assert!(!is_bare_semver("^1.2.3"));
52	        assert!(!is_bare_semver("a.b.c"));
53	        assert!(!is_bare_semver(""));
