94	pub struct TagIndex {
95	    last: BTreeMap<PackageId, Option<LastTag>>,
96	    templates: BTreeMap<PackageId, TagTemplate>,
97	    pre_cursor: BTreeMap<PackageId, Option<CommitSha>>,
98	    pub diagnostics: Vec<Diagnostic>,
99	}
