101	impl TagIndex {
102	    pub fn build<R: CommandRunner, D: DependencyResolver>(
103	        runner: &R,
104	        root: &Path,
105	        graph: &D,
106	        _cfg: &ResolvedConfig,
107	    ) -> Result<Self, GraphError> {
108	        let mut last = BTreeMap::new();
109	        let mut templates = BTreeMap::new();
110	        let mut pre_cursor = BTreeMap::new();
111	        let diagnostics = Vec::new();
112	
113	        // Fetch the raw tag list exactly once for the whole build, not once
114	        // per package -- see `fetch_all_tags` for why (avoids N gix
115	        // discoveries / N host round-trips for N packages).
116	        let all_tags = fetch_all_tags(runner, root)?;
117	
118	        for pkg in graph.packages() {
119	            let default_tmpl =
120	                TagTemplate::parse(&format!("{}@{{version}}", pkg.id.display_name()))?;
121	            let tmpl = pkg.tag_template.clone().unwrap_or(default_tmpl);
122	            let sel = select_from_tags(&all_tags, &tmpl, pkg.version_grammar()?)?;
123	            last.insert(pkg.id.clone(), sel.chosen);
124	            templates.insert(pkg.id.clone(), tmpl);
125	            pre_cursor.insert(pkg.id.clone(), None);
126	        }
127	
128	        Ok(TagIndex {
129	            last,
130	            templates,
131	            pre_cursor,
132	            diagnostics,
133	        })
134	    }
