        let sha = CommitSha::parse(&sha40('c')).unwrap();
        advance_pre_cursor(&AssertingRunner, Path::new("."), &id, &sha).unwrap();
    }

    #[test]
    fn advance_pre_cursor_succeeds_when_update_ref_succeeds() {
