//! Regression tests for callisto_manifests::persist_call_count/reset_persist_call_count.
//! Isolated in its own integration-test binary because PERSIST_CALL_COUNT is a
//! process-global counter that other, non-#[serial] tests in the `--lib` binary
//! (spread across cargo.rs's/npm.rs's/python.rs's own test modules) would
//! pollute -- see crates/callisto-graph/tests/apply_persist_open_count_test.rs's
//! identical documented precedent for OPEN_CALL_COUNT.

use std::fs;

use callisto_manifests::{open, Manifest, OpenContext};
use callisto_model::{ApplyPermit, ManifestDecl, ManifestFormat, ManifestRole};
use serial_test::serial;

fn permit() -> ApplyPermit {
    ApplyPermit::force_for_tests()
}

#[test]
#[serial]
fn cargo_persist_increments_persist_call_count_on_success() {
    let dir = tempfile::tempdir().unwrap();
    let manifest_path = dir.path().join("Cargo.toml");
    let content = "[package]\nname = \"my-crate\"\nversion = \"0.1.0\"\n";
    fs::write(&manifest_path, content).unwrap();

    let decl = ManifestDecl::new(
        "Cargo.toml",
        ManifestRole::Canonical,
        ManifestFormat::CargoToml,
    )
    .unwrap();
    let ctx = OpenContext {
        workspace_root: dir.path(),
        cargo_workspace: None,
        npm_workspace_kind: None,
    };
    let mut manifest = open(&decl, &ctx).unwrap();

    callisto_manifests::reset_persist_call_count();
    manifest.persist(&permit()).unwrap();

    assert_eq!(
        callisto_manifests::persist_call_count(),
        1,
        "a successful persist() must increment PERSIST_CALL_COUNT by exactly 1"
    );
}
```",
  "test_command": "cargo test -p callisto-manifests --test persist_call_count_test cargo_persist_increments_persist_call_count_on_success",
  "expected_failure": "error[E0425]: cannot find function `reset_persist_call_count` in module `callisto_manifests`
  --> crates/callisto-manifests/tests/persist_call_count_test.rs: `callisto_manifests::reset_persist_call_count();`
error[E0425]: cannot find function `persist_call_count` in module `callisto_manifests`
  --> crates/callisto-manifests/tests/persist_call_count_test.rs: `callisto_manifests::persist_call_count(),`
(callisto_manifests::open/Manifest/OpenContext all resolve fine -- only the two new functions are undefined, so the crate fails to compile with E0425, not E0433)",
  "implementation": "In crates/callisto-manifests/src/lib.rs, immediately after the existing `open_call_count` function (after line 124), add:
```rust
/// Test-observability counter: total number of times a `Manifest`
/// implementor's `persist` has returned `Ok`. Production code never reads
/// this; it exists so callers can write regression tests asserting a given
/// manifest path is flushed to disk at most once per logical operation.
/// Distinct from `OPEN_CALL_COUNT` so open-count and persist-count
/// assertions in the same test are independent.
static PERSIST_CALL_COUNT: std::sync::atomic::AtomicUsize =
    std::sync::atomic::AtomicUsize::new(0);

/// Resets the internal manifest-persist call counter to zero. Intended for use in test setup.
pub fn reset_persist_call_count() {
    PERSIST_CALL_COUNT.store(0, std::sync::atomic::Ordering::SeqCst);
}

/// Reads the current value of the internal manifest-persist call counter.
pub fn persist_call_count() -> usize {
    PERSIST_CALL_COUNT.load(std::sync::atomic::Ordering::SeqCst)
}

/// Increments PERSIST_CALL_COUNT by one. Called by each Manifest
/// implementor's persist() immediately after its own atomic_write returns
/// Ok; PERSIST_CALL_COUNT itself is private to this module, so this is the
/// only way other modules in this crate may increment it.
pub(crate) fn record_persist_call() {
    PERSIST_CALL_COUNT.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
}
```
