        let mut text = self.document.to_string();
        if self.has_bom {
            text = format!("\u{FEFF}{}", text);
        }
        crate::atomic::atomic_write(&self.absolute, &text, permit).map_err(|e| {
            ManifestError::Write {
                path: self.path.clone(),
                message: e.to_string(),
            }
        })
    }
```
