10	/// A validated tag template containing prefix, suffix, and exact `{version}` placement.
11	#[derive(Clone, Debug, PartialEq, Eq, Hash)]
12	pub struct TagTemplate {
13	    prefix: String,
14	    suffix: String,
15	}
16	
17	impl TagTemplate {
18	    pub fn parse(raw: &str) -> Result<Self, TagTemplateError> {
19	        let version_marker = "{version}";
20	        let count = raw.matches(version_marker).count();
21	        if count == 0 {
22	            if let Some(start) = raw.find('{') {
23	                if let Some(end) = raw[start..].find('}') {
24	                    let placeholder = &raw[start + 1..start + end];
25	                    return Err(TagTemplateError::UnknownPlaceholder {
26	                        template: raw.to_string(),
27	                        placeholder: placeholder.to_string(),
28	                    });
29	                }
30	            }
31	            return Err(TagTemplateError::MissingVersionPlaceholder {
32	                template: raw.to_string(),
33	            });
34	        }
35	        if count > 1 {
36	            return Err(TagTemplateError::MultipleVersionPlaceholders {
37	                template: raw.to_string(),
38	                count,
39	            });
40	        }
41	
42	        let (prefix, suffix) = raw.split_once(version_marker).unwrap();
43	
44	        if prefix.is_empty() && suffix.is_empty() {
45	            return Err(TagTemplateError::NoLiteralAnchor {
46	                template: raw.to_string(),
47	            });
48	        }
49	
50	        for (part, _name) in [(prefix, "prefix"), (suffix, "suffix")] {
51	            for ch in part.chars() {
52	                if matches!(ch, '*' | '?' | '[' | ']') {
53	                    return Err(TagTemplateError::GlobMetacharacterInLiteral {
54	                        template: raw.to_string(),
55	                        ch,
56	                    });
57	                }
58	            }
59	        }
60	
61	        let test_render = format!("{prefix}1.0.0{suffix}");
62	        if !is_valid_git_ref_name(&test_render) {
63	            return Err(TagTemplateError::InvalidGitRefName {
64	                template: raw.to_string(),
65	                rendered: test_render,
66	            });
67	        }
68	
69	        Ok(TagTemplate {
70	            prefix: prefix.to_string(),
71	            suffix: suffix.to_string(),
72	        })
73	    }
74	
75	    pub fn default_for(id: &PackageId) -> Self {
76	        TagTemplate {
77	            prefix: format!("{}@", id.display_name()),
78	            suffix: String::new(),
79	        }
80	    }
81	
82	    pub fn render(&self, version: &Version) -> TagName {
83	        TagName(format!(
84	            "{}{}{}",
85	            self.prefix,
86	            version.render(),
87	            self.suffix
88	        ))
89	    }
90	
91	    pub fn render_floating_major(&self, version: &Version) -> Option<TagName> {
92	        let major = version.major()?;
93	        let rendered = format!("{}{}{}", self.prefix, major, self.suffix);
94	        if is_valid_git_ref_name(&rendered) {
95	            Some(TagName(rendered))
96	        } else {
97	            None
98	        }
99	    }
100	
101	    pub fn glob(&self) -> String {
102	        format!("{}*{}", self.prefix, self.suffix)
103	    }
104	
105	    pub fn extract_version_str<'a>(&self, tag: &'a str) -> Option<&'a str> {
106	        if !tag.starts_with(&self.prefix) || !tag.ends_with(&self.suffix) {
107	            return None;
108	        }
109	        let end_idx = tag.len() - self.suffix.len();
110	        if end_idx < self.prefix.len() {
111	            return None;
112	        }
113	        Some(&tag[self.prefix.len()..end_idx])
114	    }
115	
116	    pub fn as_str(&self) -> String {
117	        format!("{}{{version}}{}", self.prefix, self.suffix)
118	    }
119	}
120	
121	impl Serialize for TagTemplate {
122	    fn serialize<S>(&self, serializer: S) -> Result<S::Ok, S::Error>
123	    where
124	        S: Serializer,
125	    {
126	        serializer.serialize_str(&self.as_str())
127	    }
128	}
129	
130	impl<'de> Deserialize<'de> for TagTemplate {
131	    fn deserialize<D>(deserializer: D) -> Result<Self, D::Error>
132	    where
133	        D: Deserializer<'de>,
134	    {
135	        let s = String::deserialize(deserializer)?;
136	        TagTemplate::parse(&s).map_err(serde::de::Error::custom)
137	    }
138	}
139	
140	fn is_valid_git_ref_name(s: &str) -> bool {
141	    if s.is_empty() || s.starts_with('/') || s.ends_with('/') || s.contains("//") || s == "@" {
142	        return false;
143	    }
144	    if s.contains("..") || s.contains("@{") {
145	        return false;
146	    }
147	    for component in s.split('/') {
148	        if component.starts_with('.') || component.ends_with(".lock") {
149	            return false;
150	        }
151	    }
152	    for ch in s.chars() {
