/// Strips a URL's userinfo component (`user:pass@` between `scheme://`
/// and the host) from every `scheme://...` occurrence in `text`,
/// replacing it with `[REDACTED]@`. Operates token-by-token: a
/// `scheme://` is only treated as carrying userinfo if an `@` appears
/// before the next `/`, whitespace, or quote character, so a bare
/// `https://registry.npmjs.org/pkg` (no userinfo) is left untouched.
fn redact_url_userinfo(text: &str) -> String {
    let mut result = String::with_capacity(text.len());
    let mut rest = text;
    while let Some(scheme_pos) = rest.find("://") {
        let split_at = scheme_pos + 3;
        result.push_str(&rest[..split_at]);
        let after = &rest[split_at..];
        let stop = after
            .find(|c: char| c.is_whitespace() || matches!(c, '"' | '\'' | '<' | '>'))
            .unwrap_or(after.len());
        let candidate = &after[..stop];
        if let Some(at_pos) = candidate.find('@') {
            if !candidate[..at_pos].contains('/') {
                result.push_str("[REDACTED]@");
                rest = &after[at_pos + 1..];
                continue;
            }
        }
        rest = after;
    }
    result.push_str(rest);
    result
}

